import{_ as a,o as t,c as s,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Sauvegarder et restaurer le travail local","description":"","frontmatter":{"title":"Sauvegarder et restaurer le travail local","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"8d4c1c22be78540b85ff938603d818d98cb9dbe33bbaa868edb9327de83971a4","order":20},"headers":[],"relativePath":"fr/user/preferences/backups.md","filePath":"fr/user/preferences/backups.md","lastUpdated":1794611623000}'),o={name:"fr/user/preferences/backups.md"};function i(n,e,l,d,c,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="back-up-and-restore-local-work" tabindex="-1">Sauvegarder et restaurer le travail local <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;Sauvegarder et restaurer le travail local {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Préserver une configuration fonctionnelle avant les mises à jour, réinitialisations ou changements d’ordinateur. Il faut un stockage que vous contrôlez et le temps de fermer TikTools proprement. L’interface actuelle n’a pas de bouton universel <strong>Back up everything</strong> ; utilisez les exportations spécifiques et une copie des données avec l’application fermée.</p><h2 id="export-reusable-definitions" tabindex="-1">Exporter les définitions réutilisables <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;Exporter les définitions réutilisables {#export-reusable-definitions}&quot;">​</a></h2><ol><li>Dans <strong>Automations</strong>, sélectionnez le profil voulu et utilisez son action d’exportation pour enregistrer un fichier <code>.tikprofile.json</code>. Nommez-le avec la version de l’application et la date.</li><li>Pour un seul modèle réutilisable, utilisez la commande de téléchargement/exportation de la boîte de dialogue des modèles pour enregistrer <code>.tiktemplate.json</code> lorsqu’elle est proposée.</li><li>Examinez le fichier exporté avant de le partager. Les modèles peuvent contenir des destinations et valeurs de configuration. L’exportation d’un profil ne copie ni les soldes, ni les statistiques, variables d’exécution, fichiers multimédias ou identifiants de compte.</li></ol><h2 id="copy-the-local-data" tabindex="-1">Copier les données locales <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;Copier les données locales {#copy-the-local-data}&quot;">​</a></h2><ol><li>Arrêtez l’activité LIVE et tout service de collaboration, puis quittez TikTools normalement. Attendez que l’hôte ait cessé d’écrire.</li><li>Repérez la racine de données active. Les valeurs par défaut sont <code>%LOCALAPPDATA%\\TikTools</code> sous Windows et <code>~/.local/share/TikTools</code> sous Linux, ou <code>TikTools</code> sous <code>XDG_DATA_HOME</code> si configuré. Un <code>TIKTOOLS_HOME</code> personnalisé ou une surcharge par répertoire modifie cet emplacement.</li><li>Copiez la racine et les répertoires de données, plugins, plugin-data et plugin-store redéfinis séparément dans un dossier de sauvegarde daté. Copiez tout le répertoire de base de données fermée, y compris les fichiers annexes SQLite présents, plutôt que de sélectionner un seul fichier <code>.db</code>.</li><li>Conservez séparément les fichiers audio référencés : les actions audio gardent des chemins plutôt que d’importer les octets des sons. Notez la version de l’application et les emplacements personnalisés avec la sauvegarde.</li><li>Protégez la copie car la configuration locale peut contenir des valeurs privées. L’authentification Cloud réside dans le coffre d’identifiants du système d’exploitation et n’est pas transportée par cette copie de dossier.</li></ol><h2 id="restore-and-verify" tabindex="-1">Restaurer et vérifier <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;Restaurer et vérifier {#restore-and-verify}&quot;">​</a></h2><p>Avec TikTools fermé, conservez le dossier actuel comme copie de récupération distincte. Restaurez les fichiers enregistrés aux emplacements voulus et démarrez une version compatible. Examinez la sélection du profil, les soldes, variables et chemins multimédias avant de vous reconnecter. Pour les définitions portables, importez le profil/modèle exporté via Automations ; les définitions importées restent désactivées jusqu’à leur activation explicite.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Résultat attendu, état et récupération <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Résultat attendu, état et récupération {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Les copies réalisées avec l’application fermée et les outils d’importation/exportation nommés sont des méthodes de récupération disponibles, sans garantie universelle de restauration entre versions. Cloud Changes n’est pas une sauvegarde complète. Si une version rejette les données restaurées, arrêtez-vous et revenez à la copie préservée ; réinstaller un ancien binaire n’annule pas une migration de base de données. Consultez les <a href="./../updates.html">mises à jour</a> et le <a href="./troubleshooting.html">dépannage</a>.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Les chemins individuels priment sur <code>TIKTOOLS_HOME</code> : <code>TIKTOOLS_DATA_DIR</code> contient les bases, <code>TIKTOOLS_PLUGINS_DIR</code> les paquets, <code>TIKTOOLS_PLUGIN_DATA_DIR</code> leur état et <code>TIKTOOLS_PLUGIN_STORE_DIR</code> le magasin de paquets. <code>TIKTOOLS_LOG_DIR</code> et <code>TIKTOOLS_TEMP_DIR</code> choisissent journaux et fichiers temporaires. Les chemins relatifs dépendent du dossier de lancement. Avant sauvegarde, consultez <code>tiktools api call system.info --json</code> et notez les variables héritées ; copiez données/paquets/état avec l’hôte arrêté, y compris les WAL/SHM existants. Les journaux ne remplacent pas les bases.</p><p><code>system.info</code> indique home/dataDir effectifs ; résolvez les autres dossiers depuis l’environnement réel de lancement de l’hôte, pas un autre terminal. Utilisez <code>system.health</code> pour ready/attentes analytiques et compteurs LIVE.</p>',14)])])}const f=a(o,[["render",i]]);export{m as __pageData,f as default};
